extends Camera3D
## Third-person chase camera: fixed world-axis offset behind and above the robot, smoothed.

@export var target_path: NodePath
@export var offset := Vector3(0.0, 5.0, 5.0)
@export var smoothing := 6.0

var _target: Node3D


func _ready() -> void:
	_target = get_node_or_null(target_path)
	snap()


func snap() -> void:
	if _target:
		global_position = _desired() if is_inside_tree() else _target.global_position + offset
		look_at(_target.global_position + Vector3(0, 0.6, 0), Vector3.UP)


func _desired() -> Vector3:
	# pull the camera in front of any world geometry between the robot and the ideal position (D4)
	var focus := _target.global_position + Vector3(0, 0.6, 0)
	var ideal := _target.global_position + offset
	var space := get_world_3d().direct_space_state
	var q := PhysicsRayQueryParameters3D.create(focus, ideal, 1)
	var hit := space.intersect_ray(q)
	if hit.is_empty():
		return ideal
	occluded = true
	return hit["position"] + hit["normal"] * 0.35


var occluded := false


func _process(delta: float) -> void:
	if _target == null:
		return
	occluded = false
	var desired := _desired()
	global_position = global_position.lerp(desired, 1.0 - exp(-smoothing * delta))
	look_at(_target.global_position + Vector3(0, 0.6, 0), Vector3.UP)
